theorem outer_measure_definitions_are_equivalent {n : ℕ} (S : Set (EuclideanSpace ℝ (Fin n))) :
  let IsOpenRectangle (R : Set (EuclideanSpace ℝ (Fin n))) : Prop :=
    ∃ (a b : Fin n → ℝ), R = Set.pi Set.univ fun i => Set.Ioo (a i) (b i)
  let m_star :=
    sInf {c | ∃ (R : ℕ → Set (EuclideanSpace ℝ (Fin n))),
      (∀ j, IsOpenRectangle (R j)) ∧ S ⊆ (⋃ j, R j) ∧ c = ∑' j, volume (R j)}
  let mu_star :=
    sInf {c | ∃ (I : Type) (_ : Encodable I) (R : I → Set (EuclideanSpace ℝ (Fin n))),
      (∀ j, IsOpenRectangle (R j)) ∧ S ⊆ (⋃ j, R j) ∧ c = ∑' j, volume (R j)}
  mu_star = m_star := by sorry
